const int moveX[] = {1, -1, 0, 0};
const int moveY[] = {0, 0, 1, -1};

int gridSize, maxTime, startX, startY;
string gridLabels[20], gridValues[20];
int memo[12][12][12][12][62];
int capacity[250][250], parent[250];
int distMap[20][20], visited[20][20];

inline bool isAccessible(int x, int y){
	return 0 <= x && x < gridSize && 0 <= y && y < gridSize && gridLabels[x][y] != 'Y' && gridLabels[x][y] != 'Z';
}

void computeDistances(){
	memset(distMap, 0x3f, sizeof(distMap));
	memset(visited, 0, sizeof(visited));
	distMap[startX][startY] = 0;
	visited[startX][startY] = 1;
	queue<int> qx, qy;
	qx.push(startX);
	qy.push(startY);
	while(!qx.empty()){
		int x = qx.front(); qx.pop();
		int y = qy.front(); qy.pop();
		for(int k = 0; k < 4; k++){
			int nx = x + moveX[k];
			int ny = y + moveY[k];
			if(isAccessible(nx, ny) && !visited[nx][ny]){
				distMap[nx][ny] = distMap[x][y] + 1;
				visited[nx][ny] = 1;
				qx.push(nx);
				qy.push(ny);
			}
		}
	}
}

int findPath(int xA, int yA, int xB, int yB, int step){
	if(step > maxTime)return 0;
	int &res = memo[xA][yA][xB][yB][step];
	if(res != -1)return res;
	if(xA == xB && yA == yB)return distMap[xA][yA] >= step;
	if(distMap[xA][yA] <= step)return res = 0;
	for(int k = 0; k < 4; k++){
		int nx = xA + moveX[k];
		int ny = yA + moveY[k];
		if(isAccessible(nx, ny) && findPath(nx, ny, xB, yB, step + 1))return res = 1;
	}
	return res = 0;
}

bool flowNetwork(int s, int t){
	memset(parent, -1, sizeof(parent));
	parent[s] = -2;
	queue<int> q;
	q.push(s);
	while(!q.empty()){
		int v = q.front(); q.pop();
		for(int i = s; i <= t; i++){
			if(parent[i] == -1 && capacity[v][i] > 0){
				parent[i] = v;
				q.push(i);
			}
		}
	}
	return parent[t] != -1;
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout << fixed << setprecision(32);

	cin >> gridSize >> maxTime;
	for(int i = 0; i < gridSize; i++){
