	}
	vector<pair<int, int>> nodes;
	vector<int> loadCap, supplyCap;
	for(int i = 0; i < gridSize; i++){
		for(int j = 0; j < gridSize; j++){
			if(gridValues[i][j] == 'Z'){
				startX = i;
				startY = j;
