			}
		}
	}
	int m = (int)nodes.size();
	memset(capacity, 0, sizeof(capacity));
	for(int i = 0; i < m; i++){
		capacity[0][i + 1] = supplyCap[i];
		capacity[m + 1 + i][2 * m + 1] = loadCap[i];
	}
	computeDistances();
	memset(memo, -1, sizeof(memo));
	for(int i = 0; i < m; i++){
		for(int j = 0; j < m; j++){
			if(findPath(nodes[i].first, nodes[i].second, nodes[j].first, nodes[j].second, 0)){
				capacity[i + 1][m + 1 + j] = 1000;
			}
		}
	}
	int totalFlow = 0;
	while(flowNetwork(0, 2 * m + 1)){
		int current = 2 * m + 1;
		int flowVal = 1e6;
		while(parent[current] >= 0){
			flowVal = min(flowVal, capacity[parent[current]][current]);
			current = parent[current];
		}
		current = 2 * m + 1;
		while(parent[current] >= 0){
			capacity[parent[current]][current] -= flowVal;
			capacity[current][parent[current]] += flowVal;
